suppressMessages(library(MARVEL)); options(warn=1)
m <- readRDS(system.file('extdata/data/marvel.demo.rds', package = 'MARVEL')); cat('demo PSI names:', names(m$PSI), '\n')
cat('ComputePSI formals:', paste(names(formals(MARVEL::ComputePSI)), collapse=','), '\n')
print(head(m$IntronCounts[,1:3],3)); print(colnames(m$SpliceFeature$RI)); print(head(m$SpliceFeature$RI$tran_id, 2))
mm <- CreateMarvelObject(SpliceJunction = m$SpliceJunction, SplicePheno = m$SplicePheno, SpliceFeature = m$SpliceFeature, IntronCounts = m$IntronCounts, GeneFeature = m$GeneFeature, Exp = m$Exp)
print(names(mm))
r <- withCallingHandlers(tryCatch(ComputePSI(mm, CoverageThreshold = 10, EventType = 'RI'), error = function(e) { cat('ERR:', conditionMessage(e), '\n'); print(sys.calls()[max(1, length(sys.calls()) - 8):length(sys.calls())]); NULL }))
mm2 <- CreateMarvelObject(SpliceJunction = m$SpliceJunction, SplicePheno = m$SplicePheno, SpliceFeature = m$SpliceFeature, IntronCounts = m$IntronCounts, GeneFeature = m$GeneFeature, Exp = m$Exp)
r <- tryCatch(ComputePSI(mm2, CoverageThreshold = 10, UnevenCoverageMultiplier = 10, EventType = 'RI', ), error = function(e) {cat('ERR2:', conditionMessage(e), '\n'); NULL}); cat('with UnevenCoverageMultiplier:', !is.null(r), '\n')
